-- PAWORA - full demo data dump
--
-- Generated by database/export-demo-dump.php on 2026-09-27 14:53:54
--
-- This contains the complete research-backed product catalogue
-- (95 products, provenance and prices included),
-- the adoption listings, and a small set of demonstration content.
--
-- IMPORT INSTRUCTIONS
--   1. Create an empty database.
--   2. Select that database in phpMyAdmin so its name shows in the sidebar.
--   3. Import -> choose this file -> character set utf8mb4 -> Go.
--
--   The file drops and recreates its own tables, so it safely replaces an
--   existing PAWORA install instead of merging with it.
--
--   Then set the database name and credentials for the application in
--   .env  (copy .env.example and edit it).
--
-- OMITTED ON PURPOSE: contact_messages, admin_logs, favourites, waiting lists
-- and QA rows created while testing - none of it belongs in a fresh install.
--

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

