  ('83', '6', 'Waggo', 'Waggo Splash Ceramic Dog Bowl', 'A hand-splashed ceramic dog bowl from Waggo\'s modern kitchen range, glazed in black so it reads as a design piece rather than plain petware. The stoneware body is a cooler alternative to plastic, and the wide shallow shape suits kibble, wet food or a water top-up.', '4620.00', 'LKR', 'SOURCE', 'https://www.waggo.com/products/splash-ceramic-dog-bowl', '14.00', 'USD', '329.9234', '2026-09-26', '0.00', 'W012031-01', '18', '5', 'DEMO', NULL, NULL, NULL, NULL, 'products/w012031-01.jpg', 'https://cdn.shopify.com/s/files/1/0155/5001/products/SplatterBowl.jpg', 'Black hand-splashed glazed ceramic Waggo Splash dog bowl on a plain background', 'https://www.waggo.com/products/splash-ceramic-dog-bowl', 'Waggo', 'https://www.waggo.com/products/splash-ceramic-dog-bowl', 'Active', '2026-09-27 01:21:17', '2026-09-27 05:51:30'),
  ('84', '6', 'Waggo', 'Waggo Habit Circle Dog Placemat Set of 2', 'Two silicone placemats that sit under a feeding bowl to catch splashes and stop the bowl sliding on hard floors. The Habit Circle is a low-profile ring that suits a plain bowl, and the pair means one mat can stay down while the other is wiped or moved.', '5590.00', 'LKR', 'SOURCE', 'https://www.waggo.com/products/habit-dog-placemat', '16.95', 'USD', '329.9234', '2026-09-26', '0.00', 'W063621-01', '30', '8', 'DEMO', NULL, NULL, NULL, NULL, 'products/w063621-01.jpg', 'https://cdn.shopify.com/s/files/1/0155/5001/products/circle_mats_black_1.jpg', 'Two black circular silicone Habit Circle dog placemats from Waggo', 'https://www.waggo.com/products/habit-dog-placemat', 'Waggo', 'https://www.waggo.com/products/habit-dog-placemat', 'Active', '2026-09-27 01:21:17', '2026-09-27 05:51:31'),
  ('85', '6', 'Catenary', 'Catenary Halo Ceramic Cat Bowl', 'A rounded ceramic cat bowl with a halo-like rim, made by Catenary and sold through Fable. The wide, shallow shape is designed to reduce whisker contact while a cat eats or drinks, and the human-grade ceramic body is dishwasher safe for everyday cleaning.', '9900.00', 'LKR', 'SOURCE', 'https://fablepets.com/products/halo', '30.00', 'USD', '329.9234', '2026-09-26', '0.00', 'HALO1', '12', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/halo1.png', 'https://cdn.shopify.com/s/files/1/0025/3470/3202/files/AR105916_1_1.png?width=900', 'Catenary Halo ceramic cat bowl with a raised halo rim, photographed on a plain background', 'https://fablepets.com/products/halo', 'Fable (Catenary)', 'https://fablepets.com/products/halo', 'Active', '2026-09-27 01:21:17', '2026-09-27 05:51:35'),
  ('86', '6', 'tuft + paw', 'tuft + paw Porto Cat Carrier', 'An airline-approved soft cat carrier from tuft + paw, sold through Fable. It is built from water-resistant canvas with breathable mesh windows for ventilation and visibility, and the frame unzips flat so a removable faux-shearling bed turns the same bag into a bed at the destination.', '35960.00', 'LKR', 'SOURCE', 'https://fablepets.com/products/porto-cat-carrier', '109.00', 'USD', '329.9234', '2026-09-26', '0.00', 'JI-POR-O-CH', '6', '2', 'DEMO', NULL, NULL, NULL, NULL, 'products/ji-por-o-ch.jpg', 'https://cdn.shopify.com/s/files/1/0025/3470/3202/files/Porto-Charcoal-PDP-1-min_4e191cea-c066-48a2-9729-8c9f1dc24141.jpg', 'Charcoal canvas tuft + paw Porto cat carrier with mesh windows and a shearling bed, shown folded out', 'https://fablepets.com/products/porto-cat-carrier', 'Fable (tuft + paw)', 'https://fablepets.com/products/porto-cat-carrier', 'Active', '2026-09-27 01:21:17', '2026-09-27 05:51:36'),
  ('87', '6', 'PETLIBRO', 'PETLIBRO Stainless Steel Water Fountain', 'A 304 stainless steel pet water fountain from PETLIBRO, sold with four replacement filters. The metal spout and bowl are BPA-free, rust and corrosion resistant, and the pump runs below 30dB, so it suits cats that are wary of moving water or households sensitive to pump noise.', '13195.00', 'LKR', 'SOURCE', 'https://petlibro.com/products/stainless-steel-fountain-for-pet', '39.99', 'USD', '329.9234', '2026-09-26', '0.00', 'PL-WF006-03M', '15', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/pl-wf006-03m.png', 'https://cdn.shopify.com/s/files/1/0252/5197/1119/files/WF006_4_-_Compressify.io_1_ef07c9f4-41c9-40a3-99cd-8e81f9fb6ec1.png', 'PETLIBRO stainless steel pet water fountain with a round drinking bowl and side filter housing', 'https://petlibro.com/products/stainless-steel-fountain-for-pet', 'PETLIBRO', 'https://petlibro.com/products/stainless-steel-fountain-for-pet', 'Active', '2026-09-27 01:21:17', '2026-09-27 05:51:39'),
  ('88', '6', 'PETLIBRO', 'PETLIBRO Scout Smart Pet Camera', 'An indoor camera for watching pets while the house is empty, with AI recognition that learns which animals are in frame. It streams to a phone app for live view and two-way talk, so a pet can be checked on and spoken to through the day.', '26390.00', 'LKR', 'SOURCE', 'https://petlibro.com/products/scout-smart-camera-for-pet', '79.99', 'USD', '329.9234', '2026-09-26', '0.00', 'PL-PC001-01W', '9', '3', 'DEMO', NULL, NULL, NULL, NULL, 'products/pl-pc001-01w.png', 'https://cdn.shopify.com/s/files/1/0252/5197/1119/files/scout-smart-camera-513103.png', 'White PETLIBRO Scout smart pet camera on a stand, viewed from the front', 'https://petlibro.com/products/scout-smart-camera-for-pet', 'PETLIBRO', 'https://petlibro.com/products/scout-smart-camera-for-pet', 'Active', '2026-09-27 01:21:17', '2026-09-27 05:51:40'),
  ('89', '6', 'PETKIT', 'PETKIT Breezy 2 Cat Carrier', 'A backpack-style cat carrier from PETKIT with a built-in fan for ventilation and a control for wind speed and light. Air vents, mesh panels and a self-locking zipper keep a cat secure, while padded shoulder straps spread the weight when it is worn for vet trips.', '24740.00', 'LKR', 'SOURCE', 'https://www.petkit.com/products/breezy-dome-2', '74.99', 'USD', '329.9234', '2026-09-26', '0.00', 'BP2-PINK', '8', '3', 'DEMO', NULL, NULL, NULL, NULL, 'products/bp2-pink.png', 'https://cdn.shopify.com/s/files/1/0569/0526/9388/products/breezy-2-cat-carrier-gradient-pink-blue-product-display.png', 'PETKIT Breezy 2 backpack cat carrier in a pink and blue gradient, shown from the front', 'https://www.petkit.com/products/breezy-dome-2', 'PETKIT', 'https://www.petkit.com/products/breezy-dome-2', 'Active', '2026-09-27 01:21:17', '2026-09-27 05:51:42'),
  ('90', '6', 'PETKIT', 'PETKIT Raised Feeder Stand', 'A raised stand that lifts a bowl or feeder off the floor to a more comfortable eating height, which can help digestion and posture. It is moulded from BPA-free, food-grade material with anti-slip pads underneath, a cable notch for a power lead, and a surface that wipes clean.', '6595.00', 'LKR', 'SOURCE', 'https://www.petkit.com/products/petkit-raised-stand', '19.99', 'USD', '329.9234', '2026-09-26', '0.00', 'DP1', '20', '5', 'DEMO', NULL, NULL, NULL, NULL, 'products/dp1.png', 'https://cdn.shopify.com/s/files/1/0569/0526/9388/products/petkit-raised-stand-product-display.png', 'PETKIT raised feeder stand in cream, shown with a bowl resting on top', 'https://www.petkit.com/products/petkit-raised-stand', 'PETKIT', 'https://www.petkit.com/products/petkit-raised-stand', 'Active', '2026-09-27 01:21:17', '2026-09-27 05:51:44'),
  ('91', '6', 'Roverlund', 'Roverlund Out-of-Office Collapsible Dog Bowl', 'A collapsible waterproof dog bowl that folds flat for a bag or car door pocket and springs back open for water on a walk. It suits both food and water, so it works on a hike, at training class, or anywhere a public bowl is not available.', '6270.00', 'LKR', 'SOURCE', 'https://roverlund.com/products/collapsible-dog-bowl', '19.00', 'USD', '329.9234', '2026-09-26', '0.00', '11122', '25', '6', 'DEMO', NULL, NULL, NULL, NULL, 'products/11122.jpg', 'https://cdn.shopify.com/s/files/1/0032/7050/8659/products/roverlunddogbowl_updated_5.2.22.jpg', 'Roverlund collapsible dog bowl in black, shown folded flat next to its expanded form', 'https://roverlund.com/products/collapsible-dog-bowl', 'Roverlund', 'https://roverlund.com/products/collapsible-dog-bowl', 'Active', '2026-09-27 01:21:17', '2026-09-27 05:51:47'),
  ('92', '6', 'Roverlund', 'Roverlund Leader-of-the-Pack Poop Bag Holder', 'A clip-on holder for a roll of poop bags that keeps waste kit off the lead handle and one-handed at the start of a walk. It is a small travel essential for dog owners who forget the bags, and it attaches to most leads and harnesses with a strap loop.', '6270.00', 'LKR', 'SOURCE', 'https://roverlund.com/products/leader-of-the-pack-poop-bag-holder', '19.00', 'USD', '329.9234', '2026-09-26', '0.00', '11113', '28', '6', 'DEMO', NULL, NULL, NULL, NULL, 'products/11113.jpg', 'https://cdn.shopify.com/s/files/1/0032/7050/8659/products/4747_JK_Co092221_31_for_web_7e9ad5c7-d762-438d-9a7e-5cc87bd31753.jpg', 'Roverlund camo and orange poop bag holder attached to a lead handle with a bag roll inside', 'https://roverlund.com/products/leader-of-the-pack-poop-bag-holder', 'Roverlund', 'https://roverlund.com/products/leader-of-the-pack-poop-bag-holder', 'Active', '2026-09-27 01:21:17', '2026-09-27 05:51:48'),
  ('94', '7', 'K&H Pet Products', 'K&H Original Pet Cot', 'K&H\'s classic raised pet cot, sold from Small 17 x 22 in through X-Large 32 x 50 in with green, charcoal or chocolate covers. A simple off-the-floor perch for cats and small dogs that keeps them off cold tiles and draughts, and it folds down for storage.', '8230.00', 'LKR', 'SOURCE', 'https://khpet.com/products/original-pet-cot', '24.95', 'USD', '329.9234', '2026-09-26', '0.00', '100212972', '18', '5', 'DEMO', NULL, NULL, NULL, NULL, 'products/100212972.jpg', 'https://cdn.shopify.com/s/files/1/0272/4770/6214/files/Original_Pet_Cot_GREEN_MED_DEAL.jpg?v=1772489446', 'K&H Original Pet Cot raised bed in chocolate with black trim', 'https://khpet.com/products/original-pet-cot', 'K&H Pet Products', 'https://khpet.com/products/original-pet-cot', 'Active', '2026-09-27 02:06:58', '2026-09-27 05:51:50'),
  ('95', '7', 'K&H Pet Products', 'K&H Self-Warming Nuzzle Nest Pet Bed', 'A self-warming pet bed from K&H that works off the animal\'s own body heat, so it needs no power. The deep nuzzle-nest shape gives a dog or cat a curled, den-like place to settle, which makes it a practical cold-weather addition indoors.', '11540.00', 'LKR', 'SOURCE', 'https://khpet.com/products/self-warming-nuzzle-nest', '34.98', 'USD', '329.9234', '2026-09-26', '0.00', '100213086', '18', '5', 'DEMO', NULL, NULL, NULL, NULL, 'products/100213086.jpg', 'https://cdn.shopify.com/s/files/1/0272/4770/6214/products/self-warming-nuzzle-nest-6.jpg?v=1741807743', 'K&H Self-Warming Nuzzle Nest Pet Bed, round self-warming pet bed', 'https://khpet.com/products/self-warming-nuzzle-nest', 'K&H Pet Products', 'https://khpet.com/products/self-warming-nuzzle-nest', 'Active', '2026-09-27 02:06:58', '2026-09-27 05:51:51'),
  ('96', '7', 'K&H Pet Products', 'K&H Original Bolster Pet Cot', 'A raised cot with padded bolsters along three sides, so a dog can rest its head without rolling off. K&H lists it from Small 17 x 22 in to Large 30 x 42 in in chocolate or charcoal, giving a boxed-in feel that suits nervous or older dogs.', '14830.00', 'LKR', 'SOURCE', 'https://khpet.com/products/k-h-original-bolster-pet-cot', '44.95', 'USD', '329.9234', '2026-09-26', '0.00', '100213497', '18', '5', 'DEMO', NULL, NULL, NULL, NULL, 'products/100213497.jpg', 'https://cdn.shopify.com/s/files/1/0272/4770/6214/files/BolsterCotLargeCharcoalv2.jpg?v=1741807841', 'K&H Original Bolster Pet Cot in chocolate with raised padded sides', 'https://khpet.com/products/k-h-original-bolster-pet-cot', 'K&H Pet Products', 'https://khpet.com/products/k-h-original-bolster-pet-cot', 'Active', '2026-09-27 02:06:58', '2026-09-27 05:51:52'),
  ('97', '7', 'K&H Pet Products', 'K&H All Season All Weather Dog Cot', 'An outdoor-style raised cot for dogs, sized from Medium 32 x 25 in up to Jumbo 56 x 38 in in tan, gray or green. The open frame suits decks, kennels and patios, giving a dog a dry raised spot to lie in sun or shade.', '11530.00', 'LKR', 'SOURCE', 'https://khpet.com/products/all-weather-pet-cot-elevated-pet-bed', '34.95', 'USD', '329.9234', '2026-09-26', '0.00', '100213623', '18', '5', 'DEMO', NULL, NULL, NULL, NULL, 'products/100213623.jpg', 'https://cdn.shopify.com/s/files/1/0272/4770/6214/files/AllWeatherPetCot_Jumbo_Tan_MAINIMAGE_REV0copy.jpg?v=1741807484', 'K&H All Season All Weather Dog Cot in gray, raised outdoor dog bed', 'https://khpet.com/products/all-weather-pet-cot-elevated-pet-bed', 'K&H Pet Products', 'https://khpet.com/products/all-weather-pet-cot-elevated-pet-bed', 'Active', '2026-09-27 02:06:58', '2026-09-27 05:51:53'),
  ('98', '7', 'PETSFIT', 'PETSFIT Elevated Dog Bed for Large Dogs', 'A low-profile raised dog bed from PETSFIT, sized Medium 42 x 30 in and Large 48 x 33 in. The elevated frame suits bigger dogs that want a flat, dry place to lie instead of a cushioned bolster.', '15820.00', 'LKR', 'SOURCE', 'https://petsfit.com/products/petsfit-elevated-dog-bed-large-dogs', '47.95', 'USD', '329.9234', '2026-09-26', '0.00', 'DCCD022034L1', '18', '5', 'DEMO', NULL, NULL, NULL, NULL, 'products/dccd022034l1.jpg', 'https://cdn.shopify.com/s/files/1/0627/5930/5406/files/petsfit-simple-dog-bed-low-profile-gray_4_137ba2a9-012b-4ab6-a31a-0f0dd1cf09b5.jpg?v=1773282604', 'PETSFIT elevated dog bed in gray, low profile raised frame', 'https://petsfit.com/products/petsfit-elevated-dog-bed-large-dogs', 'PETSFIT', 'https://petsfit.com/products/petsfit-elevated-dog-bed-large-dogs', 'Active', '2026-09-27 02:06:58', '2026-09-27 05:51:55'),
  ('99', '7', 'K&H Pet Products', 'K&H Thermo Pet Cuddler Indoor Heated Donut Cat Bed', 'A heated donut-style bed for indoor cats, with a raised rim that keeps a curled body tucked in. The Thermo Pet Cuddler is listed as a single indoor model, aimed at cats that look for a warm enclosed spot in the cooler months.', '23090.00', 'LKR', 'SOURCE', 'https://khpet.com/products/k-h-thermo-pet-cuddler-indoor-heated-donut-cat-bed', '69.98', 'USD', '329.9234', '2026-09-26', '0.00', '100553013', '18', '5', 'DEMO', NULL, NULL, NULL, NULL, 'products/100553013.jpg', 'https://cdn.shopify.com/s/files/1/0272/4770/6214/files/100553013_ROUNDCORDCUDDLER_SILO_WITH_CAT.jpg?v=1773252560', 'K&H Thermo Pet Cuddler heated donut cat bed with raised rim', 'https://khpet.com/products/k-h-thermo-pet-cuddler-indoor-heated-donut-cat-bed', 'K&H Pet Products', 'https://khpet.com/products/k-h-thermo-pet-cuddler-indoor-heated-donut-cat-bed', 'Active', '2026-09-27 02:06:58', '2026-09-27 05:51:57'),
  ('100', '7', 'PETSFIT', 'Petsfit Large Cat Hammock Bed', 'A large cat hammock bed from Petsfit, hung so a cat can curl up off the floor. The suspended fabric pocket suits indoor cats that like height and a tucked-in resting spot.', '19790.00', 'LKR', 'SOURCE', 'https://petsfit.com/products/petsfit-large-cat-hammock-bed-for-curling-up-for-all-sizes-cats', '59.99', 'USD', '329.9234', '2026-09-26', '0.00', 'DBW1035ZB00J', '18', '5', 'DEMO', NULL, NULL, NULL, NULL, 'products/dbw1035zb00j.jpg', 'https://cdn.shopify.com/s/files/1/0627/5930/5406/files/petsfit-large-cat-hammock-bed-for-curling-up-for-all-sizes-cats.jpg?v=1733130467', 'Petsfit large cat hammock bed with a cat curled up inside', 'https://petsfit.com/products/petsfit-large-cat-hammock-bed-for-curling-up-for-all-sizes-cats', 'Petsfit', 'https://petsfit.com/products/petsfit-large-cat-hammock-bed-for-curling-up-for-all-sizes-cats', 'Active', '2026-09-27 02:06:58', '2026-09-27 05:51:58'),
  ('101', '7', 'DIGGS', 'DIGGS Bolstr Evolv Dog Bed', 'A bolstered dog bed from DIGGS\' Bolstr Evolv range, offered from Small through XL. The shaped, cushioned build suits dogs that curl into one corner or stretch out across the middle of the bed.', '19465.00', 'LKR', 'SOURCE', 'https://diggs.pet/products/bolstr-evolv-dog-bed', '59.00', 'USD', '329.9234', '2026-09-26', '0.00', 'MCP001A24G', '18', '5', 'DEMO', NULL, NULL, NULL, NULL, 'products/mcp001a24g.jpg', 'https://cdn.shopify.com/s/files/1/0015/0811/4519/files/Bolstr_24_Left_1.jpg?v=1757787885', 'DIGGS Bolstr Evolv dog bed, small size product photo', 'https://diggs.pet/products/bolstr-evolv-dog-bed', 'DIGGS', 'https://diggs.pet/products/bolstr-evolv-dog-bed', 'Active', '2026-09-27 02:06:58', '2026-09-27 05:51:59'),
  ('102', '7', 'tuft + paw', 'tuft + paw Haven Luxury Bed', 'A deep bed with high sides from tuft + paw\'s Haven collection, sold from XS/S through L/XL in two colourways. The cushioned base and raised rim suit dogs that like to sleep tucked in rather than stretched out flat.', '65655.00', 'LKR', 'SOURCE', 'https://fablepets.com/products/bed', '199.00', 'USD', '329.9234', '2026-09-26', '0.00', 'HL-BED-DSLG1', '18', '5', 'DEMO', NULL, NULL, NULL, NULL, 'products/hl-bed-dslg1.jpg', 'https://cdn.shopify.com/s/files/1/0025/3470/3202/products/bed-mineral-grey-2_f9353ea2-1da3-4460-9e2f-1847a66aa46e_A.jpg?v=1691772279', 'tuft + paw Haven luxury dog bed in dark shadow colourway', 'https://fablepets.com/products/bed', 'tuft + paw', 'https://fablepets.com/products/bed', 'Active', '2026-09-27 02:06:58', '2026-09-27 05:51:59'),
  ('103', '8', 'Ruffwear', 'Ruffwear Crag Reflective Dog Collar', 'Ruffwear\'s everyday reflective dog collar, stocked from 9 to 26 in across a large spread of seasonal colourways. The reflective webbing helps a dog be spotted on dusk and night walks.', '8080.00', 'LKR', 'SOURCE', 'https://ruffwear.com/products/crag-reflective-dog-collar', '24.49', 'USD', '329.9234', '2026-09-26', '0.00', '25802-0351114', '18', '5', 'DEMO', NULL, NULL, NULL, NULL, 'products/25802-0351114.png', 'https://cdn.shopify.com/s/files/1/1577/4333/files/Tropicla_Bloom.png?v=1785530240', 'Ruffwear Crag reflective dog collar in granite gray', 'https://ruffwear.com/products/crag-reflective-dog-collar', 'Ruffwear', 'https://ruffwear.com/products/crag-reflective-dog-collar', 'Active', '2026-09-27 02:06:58', '2026-09-27 05:52:00'),
  ('104', '8', 'LupinePet', 'LupinePet Fi Collar Basic Solid Colors', 'A nylon webbing collar from LupinePet\'s Fi range, in solid colours at 3/4 in or 1 in width. The size run goes from 11.5 in to 32 in, so the same style covers toy dogs through larger breeds.', '14055.00', 'LKR', 'SOURCE', 'https://www.lupinepet.com/products/lupinepet-fi-collar-basic-solids', '42.60', 'USD', '329.9234', '2026-09-26', '0.00', '15015', '18', '5', 'DEMO', NULL, NULL, NULL, NULL, 'products/15015.jpg', 'https://cdn.shopify.com/s/files/1/0873/1898/7031/files/Basic_Ficollars.jpg?v=1780059604', 'LupinePet Fi collar in solid aqua nylon webbing', 'https://www.lupinepet.com/products/lupinepet-fi-collar-basic-solids', 'LupinePet', 'https://www.lupinepet.com/products/lupinepet-fi-collar-basic-solids', 'Active', '2026-09-27 02:06:58', '2026-09-27 05:52:00'),
  ('105', '8', 'GoTags', 'GoTags Personalized Reflective Dog Collar', 'An adjustable reflective collar with a quick release buckle and a silent aluminium nameplate that can be engraved. Sizes run from X-Small 8-12 in up to Large 18-26 in, and the reflective webbing helps in low light.', '5260.00', 'LKR', 'SOURCE', 'https://www.gotags.com/products/personalized-reflective-dog-collar-with-quick-release-buckle-aluminum-nameplate', '15.95', 'USD', '329.9234', '2026-09-26', '0.00', 'DOG-REFADJ-BEIGE-TAG-ALUMINUM-SMALL', '18', '5', 'DEMO', NULL, NULL, NULL, NULL, 'products/dog-refadj-beige-tag-aluminum-small.jpg', 'https://cdn.shopify.com/s/files/1/0027/4107/6077/files/ReflectiveDogCollarAluminumMain.jpg?v=1787168680', 'GoTags personalized reflective dog collar with engraved aluminium nameplate', 'https://www.gotags.com/products/personalized-reflective-dog-collar-with-quick-release-buckle-aluminum-nameplate', 'GoTags', 'https://www.gotags.com/products/personalized-reflective-dog-collar-with-quick-release-buckle-aluminum-nameplate', 'Active', '2026-09-27 02:06:58', '2026-09-27 05:52:01'),
  ('106', '8', 'Blue-9', 'Blue-9 Secure Pro Dog Collar', 'A quick release collar from Blue-9\'s Secure Pro line, stocked from Small to Large in several colours. It is the everyday collar of the Blue-9 range, sold separately from the Balance harness.', '6580.00', 'LKR', 'SOURCE', 'https://blue-9.com/products/clrm', '19.95', 'USD', '329.9234', '2026-09-26', '0.00', 'CLRM-BLK-L', '18', '5', 'DEMO', NULL, NULL, NULL, NULL, 'products/clrm-blk-l.png', 'https://cdn.shopify.com/s/files/1/0587/0816/4806/files/Blue_Secure_Pro_Collar.png?v=1747248654', 'Blue-9 Secure Pro dog collar in black, large size', 'https://blue-9.com/products/clrm', 'Blue-9', 'https://blue-9.com/products/clrm', 'Active', '2026-09-27 02:06:58', '2026-09-27 05:52:02'),
  ('107', '8', 'LupinePet', 'LupinePet Fi Collar Reflective Designs', 'The reflective version of LupinePet\'s Fi collar, with diamond and paw pattern weaves at 3/4 in or 1 in width. The size run matches the solid Fi collars, from 11.5 in to 32 in.', '14980.00', 'LKR', 'SOURCE', 'https://www.lupinepet.com/products/lupinepet-fi-collar-reflective-designs', '45.40', 'USD', '329.9234', '2026-09-26', '0.00', '48015', '18', '5', 'DEMO', NULL, NULL, NULL, NULL, 'products/48015.jpg', 'https://cdn.shopify.com/s/files/1/0873/1898/7031/files/Reflective_Ficollars.jpg?v=1790185273', 'LupinePet Fi reflective collar with blue diamond pattern nylon webbing', 'https://www.lupinepet.com/products/lupinepet-fi-collar-reflective-designs', 'LupinePet', 'https://www.lupinepet.com/products/lupinepet-fi-collar-reflective-designs', 'Active', '2026-09-27 02:06:58', '2026-09-27 05:52:03'),
