  ('133', '4', 'Chuckit!', 'Chuckit! Ultra Ball Dog Toy', 'A fetch ball with an extra thick rubber core that floats, so it works in the water as well as on land. The bright orange and blue colour is easier to spot if the ball ends up in long grass. Shown in the medium single pack.', '2965.00', 'LKR', 'SOURCE', 'https://www.petmate.com/products/chuckit-ultra-ball-dog-toy-1', '8.99', 'USD', '329.9234', '2026-09-27', '0.00', '170015', '30', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/170015.jpg', 'https://cdn.shopify.com/s/files/1/0817/1687/1489/files/170015_170015G_CI_Ultra_Ball_MD_1PK_FRONT_a46000e6-f1f3-46b9-943a-fcebc1bca82f.jpg?v=1739476023', 'Orange and blue Chuckit Ultra Ball, medium', 'https://www.petmate.com/products/chuckit-ultra-ball-dog-toy-1', 'Petmate (official Chuckit! and JW Pet distributor store)', 'https://www.petmate.com/products/chuckit-ultra-ball-dog-toy-1', 'Active', '2026-09-27 05:40:32', '2026-09-27 06:07:18'),
  ('134', '4', 'Nylabone', 'Nylabone DuraChew Bone Chew Toy, Original', 'A nylon bone chew from the DuraChew line, made for dogs that chew hard. The original flavour is offered in a regular size for smaller breeds and a wolf size for medium breeds and large puppies, made in the United States.', '2115.00', 'LKR', 'SOURCE', 'https://www.homesalive.ca/nylabone-durachew-bone-original.html', '8.99', 'CAD', '235.5087', '2026-09-27', '0.00', '17266', '18', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/17266.jpg', 'https://www.homesalive.ca/media/catalog/product/n/y/nylab-dc-original_1_.jpg', 'Nylabone DuraChew bone chew toy, original flavour', 'https://www.homesalive.ca/nylabone-durachew-bone-original.html', 'Homesalive.ca (retailer)', 'https://www.homesalive.ca/nylabone-durachew-bone-original.html', 'Active', '2026-09-27 05:40:32', '2026-09-27 06:07:18'),
  ('135', '4', 'Outward Hound', 'Outward Hound Hide A Squirrel Plush Puzzle Toy', 'A soft plush tree trunk that three squeaky animals tuck inside for a hide and seek game, and that doubles as a fetch toy once they are pulled back out. Four sizes are made, and the character can be a squirrel, bird, bee or hedgehog.', '2475.00', 'LKR', 'SOURCE', 'https://outwardhound.com/hide-a-squirrel-plush-puzzle-toy/', '7.50', 'USD', '329.9234', '2026-09-27', '0.00', 'OH-HIDE-A-SQUIRREL', '20', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/oh-hide-a-squirrel.jpg', 'https://cdn11.bigcommerce.com/s-asivtkjxr8/images/stencil/1280x1280/products/2866/11242/0e7431f61acc13e44755128420ba5c0d36cd2176__79515.1650647420.jpg?c=1', 'Outward Hound Hide A Squirrel plush puzzle toy', 'https://outwardhound.com/hide-a-squirrel-plush-puzzle-toy/', 'Outward Hound (official store)', 'https://outwardhound.com/hide-a-squirrel-plush-puzzle-toy/', 'Active', '2026-09-27 05:40:32', '2026-09-27 06:07:19'),
  ('136', '4', 'KONG', 'KONG Wubba Tug and Fetch Dog Toy', 'A soft plush body with a reinforced nylon outer and long floppy tails for tug, shake and fetch games. The tails make it easy to grip and the middle squeaks. Offered in small, large and extra large, shown here in the small size.', '3295.00', 'LKR', 'SOURCE', 'https://www.kongcompany.com/wubba/', '9.99', 'USD', '329.9234', '2026-09-27', '0.00', 'WB3', '19', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/wb3.jpg', 'https://cdn11.bigcommerce.com/s-k3kxaf4rop/images/stencil/1280x1280/products/1977/15017/94d6c0b7-6c4b-4656-8cc5-56f7ec2078da_medium__99178.1790453066.jpg?c=1', 'KONG Wubba plush tug and fetch dog toy', 'https://www.kongcompany.com/wubba/', 'KONG Company Store (official)', 'https://www.kongcompany.com/wubba/', 'Active', '2026-09-27 05:40:32', '2026-09-27 06:07:19'),
  ('137', '4', 'JW Pet', 'JW Pet Hol-ee Roller Dog Toy', 'A soft, stretchy natural rubber roller with an open middle that can be filled with treats, kibble, small toys or ice. Dogs work the pieces out from different angles, and the rubber is described as gentle on gums. Shown in the jumbo size, blue.', '6595.00', 'LKR', 'SOURCE', 'https://www.petmate.com/products/jw-hol-ee-roller-dog-toy', '19.99', 'USD', '329.9234', '2026-09-27', '0.00', '43113', '14', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/43113.jpg', 'https://cdn.shopify.com/s/files/1/0817/1687/1489/files/43113.HOLEE_ROLLER_BLUE.jpg?v=1701974298', 'Blue JW Pet Hol-ee Roller, jumbo', 'https://www.petmate.com/products/jw-hol-ee-roller-dog-toy', 'Petmate (official JW Pet seller store)', 'https://www.petmate.com/products/jw-hol-ee-roller-dog-toy', 'Active', '2026-09-27 05:40:32', '2026-09-27 06:07:20'),
  ('138', '4', 'Nina Ottosson', 'Nina Ottosson Dog Brick Treat Puzzle Toy', 'A level two treat puzzle from the Nina Ottosson line, made of tough removable plastic and free of BPA, PVC and phthalates. It has three treat hiding compartments: two under flip lids, one that slides out, and hollow brick shapes that lift away.', '3300.00', 'LKR', 'SOURCE', 'https://outwardhound.com/dog-brick.html', '10.00', 'USD', '329.9234', '2026-09-27', '0.00', '67333', '17', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/67333.jpg', 'https://cdn11.bigcommerce.com/s-asivtkjxr8/images/stencil/1280x1280/products/2150/7235/umf7ntehhv4valmyhiar__55896.1654282713.jpg?c=1', 'Nina Ottosson Dog Brick treat puzzle, blue', 'https://outwardhound.com/dog-brick.html', 'Outward Hound official store (Nina Ottosson brand page)', 'https://outwardhound.com/dog-brick.html', 'Active', '2026-09-27 05:40:32', '2026-09-27 06:07:21'),
  ('139', '4', 'Hyper Pet', 'Hyper Pet Tough Plush Tiger Toy with Squeakers', 'A plush tiger with double layer construction and edge binding, extra dense stuffing and two squeakers inside. It is sold as a durable soft toy for fetch and carry games, from a brand that makes dog toys for the US market.', '6265.00', 'LKR', 'SOURCE', 'https://www.petmate.com/products/hyper-pet-tough-plush-tiger-with-squeakers', '18.99', 'USD', '329.9234', '2026-09-27', '0.00', '50109EA', '16', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/50109ea.jpg', 'https://cdn.shopify.com/s/files/1/0817/1687/1489/files/50109_HP_Tough_Plush_Tiger_3qtr_1.jpg?v=1741118382', 'Hyper Pet tough plush tiger toy with squeakers', 'https://www.petmate.com/products/hyper-pet-tough-plush-tiger-with-squeakers', 'Petmate (official store)', 'https://www.petmate.com/products/hyper-pet-tough-plush-tiger-with-squeakers', 'Active', '2026-09-27 05:40:32', '2026-09-27 06:07:21'),
  ('140', '4', 'Catit', 'Catit Senses Play Circuit Track Toy', 'Eight snap together track sections and one circuit ball that runs a closed loop at floor level, so a cat can bat the ball and watch it travel. The layout can be rearranged into more than a hundred configurations and clips onto older Senses pieces.', '5715.00', 'LKR', 'SOURCE', 'https://catit.co.uk/products/catit-senses-circuit', '13.00', 'GBP', '439.6341', '2026-09-27', '0.00', '43154', '12', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/43154.jpg', 'https://cdn.shopify.com/s/files/1/0639/2479/7696/files/43154W-Catit-Senses-Play-Circuit-Product-Image-INT-2.jpg?v=1775807941', 'Catit Senses Play Circuit track set with ball', 'https://catit.co.uk/products/catit-senses-circuit', 'Catit official UK store (catit.co.uk)', 'https://catit.co.uk/products/catit-senses-circuit', 'Active', '2026-09-27 05:40:32', '2026-09-27 06:07:22'),
