  ('162', '3', 'Pedigree', 'Pedigree DENTASTIX Large Dog Dental Treats, Original', 'The DENTASTIX dental chew in the large size, sold in a 27.5 oz pouch containing 32 chews in the familiar stick format. It is the original flavour and the size the brand intends for bigger dogs.', '9895.00', 'LKR', 'SOURCE', 'https://southernagriculture.com/products/pedigree-dentastix-large-original-dog-treats', '29.99', 'USD', '329.9234', '2026-09-27', '0.00', '05849604347', '24', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/05849604347.png', 'https://cdn.shopify.com/s/files/1/0034/3667/5121/products/ShopifySize_3_92ef9c5b-011d-404d-9340-a943f6174ced.png?v=1642802138', 'Bag of Pedigree DENTASTIX large dog dental treats, original', 'https://www.pedigree.com/products/treats/dentastix-large-dog-dental-treats-original', 'Southern Agriculture (retailer)', 'https://southernagriculture.com/products/pedigree-dentastix-large-original-dog-treats', 'Active', '2026-09-27 05:41:09', '2026-09-27 05:53:20'),
  ('163', '3', 'Greenies', 'Greenies Original Regular Dental Treats, 6 oz', 'Greenies\' standard dental chew in the regular size, in a 6 oz bag. The same textured formula is also made in 12 oz and 36 oz bags, and this is the size most often bought first for a dog new to the treats.', '2965.00', 'LKR', 'SOURCE', 'https://chowhoundpetsupplies.com/greenies-original-regular-dental-treats/', '8.99', 'USD', '329.9234', '2026-09-27', '0.00', '76032-1', '27', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/76032-1.png', 'https://cdn11.bigcommerce.com/s-nyt6bnql2y/images/stencil/1280x1280/products/12406/102513/37081__38097.1771509882.png?c=1', 'Bag of Greenies Original regular dental treats, 6 oz', 'https://chowhoundpetsupplies.com/greenies-original-regular-dental-treats/', 'Chow Hound Pet Supplies (retailer)', 'https://chowhoundpetsupplies.com/greenies-original-regular-dental-treats/', 'Active', '2026-09-27 05:41:09', '2026-09-27 05:55:53'),
  ('164', '3', 'Milk-Bone', 'Milk-Bone Original Biscuits, Large Dog Treats', 'The brand\'s classic original dog biscuit in the large size, described by the retailer as a meatier flavour than the standard biscuits. It is the variant intended for dogs weighing fifty pounds and over, sold as an occasional snack.', '7255.00', 'LKR', 'SOURCE', 'https://www.grangecoop.com/milk-bone-meat-flavor-original-biscuits-for-large-dogs/', '21.99', 'USD', '329.9234', '2026-09-27', '0.00', '157509', '21', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/157509.png', 'https://cdn11.bigcommerce.com/s-qz13ep5fb4/products/93832/images/261835/157509__40598.1716895407.386.513.png?c=1', 'Milk-Bone original biscuits for large dogs', 'https://www.milkbone.com/dog-treats/biscuits/original-biscuits-large', 'Grange Coop (retailer)', 'https://www.grangecoop.com/milk-bone-meat-flavor-original-biscuits-for-large-dogs/', 'Active', '2026-09-27 05:41:09', '2026-09-27 05:53:21'),
  ('165', '3', 'Purina', 'Purina Beggin\' Strips Bacon Flavour Dog Treats, 25 oz', 'The bacon flavoured dog treat from the Beggin\' Strips line, in a 25 oz bag. The same treat is also sold in a 6 oz pouch, so the larger bag suits households that use treats for regular training sessions.', '4945.00', 'LKR', 'SOURCE', 'https://www.grangecoop.com/purina-beggin-strips-bacon-flavor-dog-treat-25-oz/', '14.99', 'USD', '329.9234', '2026-09-27', '0.00', '154984', '26', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/154984.jpg', 'https://cdn11.bigcommerce.com/s-vmvni2zq0j/products/37399/images/54728/1149621__59548.1500584771.500.750.jpg?c=2', 'Bag of Purina Beggin Strips bacon flavour dog treats, 25 oz', 'https://www.purina.com/dogs/shop/beggin-strips-dog-treats', 'Grange Coop (retailer)', 'https://www.grangecoop.com/purina-beggin-strips-bacon-flavor-dog-treat-25-oz/', 'Active', '2026-09-27 05:41:09', '2026-09-27 05:53:21'),
  ('166', '3', 'Blue Buffalo', 'Blue Buffalo BLUE Bits Soft Training Treats, Tempting Turkey, 4 oz', 'A soft dog training treat in the Tempting Turkey recipe, in a small 4 oz pouch sized for short training sessions. The soft texture suits dogs that are not interested in a hard, crunchy treat.', '1975.00', 'LKR', 'SOURCE', 'https://www.1800petmeds.com/dog/treats/product/blue-buffalo-bits-tempting-turkey-recipe-soft-training/prod61490.html', '5.99', 'USD', '329.9234', '2026-09-27', '0.00', '61490', '30', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/61490.jpg', 'https://imagedelivery.net/OWeDZSTbTyzlX4Fsq0SDAw/61490/public', 'Bag of Blue Buffalo BLUE Bits soft training treats, 4 oz', 'https://www.bluebuffalo.com/', '1800PetMeds (retailer)', 'https://www.1800petmeds.com/dog/treats/product/blue-buffalo-bits-tempting-turkey-recipe-soft-training/prod61490.html', 'Active', '2026-09-27 05:41:09', '2026-09-27 05:53:22'),
  ('167', '3', 'Zuke\'s', 'Zuke\'s Mini Naturals Dog Treats, Chicken Recipe, 16 oz', 'The small format treat from Zuke\'s in the Chicken Recipe, in a 16 oz pouch. This is the size usually picked up for training, where the smaller pieces are easier to hand out one at a time than full size biscuits.', '6265.00', 'LKR', 'SOURCE', 'https://www.grangecoop.com/zukes-mini-naturals-chicken-recipe-16-oz/', '18.99', 'USD', '329.9234', '2026-09-27', '0.00', '1478775', '23', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/1478775.jpg', 'https://cdn11.bigcommerce.com/s-qz13ep5fb4/products/93871/images/236302/83779eab-cb29-478c-af40-521cb01050d9__31828.1674884694.386.513.jpg?c=1', 'Bag of Zuke\'s Mini Naturals dog treats, chicken recipe, 16 oz', 'https://www.zukes.com/', 'Grange Coop (retailer)', 'https://www.grangecoop.com/zukes-mini-naturals-chicken-recipe-16-oz/', 'Active', '2026-09-27 05:41:09', '2026-09-27 05:53:22'),
  ('168', '3', 'Royal Canin', 'Royal Canin Dog Treats for Training, 8 x 110 g', 'The brand\'s training oriented snack, sold as a box of eight 110 g packs. The official UK page lists the formula as rice flour, dehydrated poultry proteins, glycerol and wheat flour, and it is aimed at owners training a dog.', '10515.00', 'LKR', 'SOURCE', 'https://www.royalcanin.com/uk/dogs/products/retail-products/training-treats-8061', '23.92', 'GBP', '439.6341', '2026-09-27', '0.00', '8-3182551063714', '15', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/8-3182551063714.jpg', 'https://marspetcareaprimocdn.petcare.global/951824f1-8393-452b-b541-b3a700c237c4/951824f1-8393-452b-b541-b3a700c237c4_DownloadAsJpg.jpg', 'Box of Royal Canin dog treats for training', 'https://www.royalcanin.com/uk/dogs/products/retail-products/training-treats-8061', 'Royal Canin UK (official brand site)', 'https://www.royalcanin.com/uk/dogs/products/retail-products/training-treats-8061', 'Active', '2026-09-27 05:41:09', '2026-09-27 05:53:23'),
  ('169', '3', 'Temptations', 'Temptations Classics Cat Treats, Tasty Chicken, 6.3 oz', 'A cat treat with a crunchy outside and a soft centre, in the Tasty Chicken flavour, in a 6.3 oz pouch. The same treat is also listed in a 16 oz size, so the small pouch works well for trying the flavour first.', '1975.00', 'LKR', 'SOURCE', 'https://www.kwikpets.com/products/temptations-classics-cat-treats-tasty-chicken-6-3-oz', '5.98', 'USD', '329.9234', '2026-09-27', '0.00', 'TC-CHIC-6OZ3', '27', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/tc-chic-6oz3.jpg', 'https://cdn.shopify.com/s/files/1/2229/1767/files/Front-6.3_de2303b5-a00f-4725-a3bd-623082c9b570.jpg?v=1752591430', 'Pouch of Temptations Classics cat treats, tasty chicken', 'https://www.temptationstreats.com/products/treats/tasty-chicken-flavor', 'Kwikpets (retailer)', 'https://www.kwikpets.com/products/temptations-classics-cat-treats-tasty-chicken-6-3-oz', 'Active', '2026-09-27 05:41:09', '2026-09-27 05:53:23'),
  ('170', '3', 'Sheba', 'Sheba Meaty Tender Sticks Cat Treats, Tuna Flavour', 'A soft, meaty cat treat stick in the Tuna flavour from the Meaty Tender Sticks line. It is one of three treat lines the brand currently makes, alongside Bisque and Premium Purees, and is sold in a single stick pouch.', '755.00', 'LKR', 'SOURCE', 'https://www.petsupermarket.com/cat/food-treats/treats/soft-chewy-treats/meaty-tender-sticks-tuna-flavor-cat-treats/FCM02537.html', '2.29', 'USD', '329.9234', '2026-09-27', '0.00', 'FCM02537', '34', '4', 'DEMO', NULL, NULL, NULL, NULL, 'products/fcm02537.jpg', 'https://www.petsupermarket.com/dw/image/v2/BGTK_PRD/on/demandware.static/-/Sites-petsupermarket-m-catalog/default/dwa155e83a/images/original/FCM02537.1.jpg?sw=800&sh=800', 'Sheba Meaty Tender Sticks cat treat, tuna flavour', 'https://www.sheba.com/cat-treats', 'Pet Supermarket (retailer)', 'https://www.petsupermarket.com/cat/food-treats/treats/soft-chewy-treats/meaty-tender-sticks-tuna-flavor-cat-treats/FCM02537.html', 'Active', '2026-09-27 05:41:09', '2026-09-27 05:55:53'),
  ('171', '3', 'PAWORA', 'PAWORA Natural Chicken Training Bites', 'Our own small training bites in a plain chicken flavour, baked into bite sized pieces that are easy to hold in one hand and quick to hand out during a training session. Sold in a resealable pouch.', '750.00', 'LKR', 'DEMO', NULL, NULL, NULL, NULL, NULL, '0.00', 'PAWORA-TRT-001', '50', '10', 'DEMO', NULL, NULL, NULL, NULL, 'products/placeholder.svg', NULL, 'PAWORA Natural Chicken Training Bites', NULL, 'PAWORA house product (no source)', NULL, 'Active', '2026-09-27 05:41:09', '2026-09-27 05:50:29');

