-- pets (8 rows)
INSERT INTO `pets` (`id`, `name`, `species`, `breed`, `age_months`, `gender`, `size`, `location`, `description`, `personality`, `health_status`, `vaccinated`, `image`, `status`, `featured`, `created_at`, `updated_at`) VALUES
  ('1', 'Luna', 'Dog', 'Golden Retriever', '24', 'Female', 'Large', 'Colombo', 'Luna is a gentle, people-focused companion who is learning to trust new friendships. She enjoys quiet walks, sunny afternoons and being part of a household.', 'Affectionate, calm, playful and thoughtful around other gentle dogs.', 'Healthy and ready for a home check.', '1', 'https://images.unsplash.com/photo-1552053831-71594a27632d?auto=format&fit=crop&w=1200&q=85', 'Available', '1', '2026-09-26 01:02:12', '2026-09-27 06:04:56'),
  ('2', 'Max', 'Dog', 'Labrador Retriever', '36', 'Male', 'Large', 'Kandy', 'Max is an optimistic, food-motivated Labrador who would love an active family and a daily routine filled with walks and games.', 'Friendly, energetic, loyal and eager to learn.', 'Healthy with routine veterinary care.', '1', 'https://images.unsplash.com/photo-1518717758536-85ae29035b6d?auto=format&fit=crop&w=1200&q=85', 'Available', '1', '2026-09-25 20:50:47', '2026-09-27 06:07:26'),
  ('3', 'Milo', 'Cat', 'Domestic Shorthair', '12', 'Male', 'Small', 'Gampaha', 'Milo is a curious young cat with a playful side. He likes window watching, soft beds and the company of people who respect his space.', 'Curious, independent, affectionate on his own terms.', 'Healthy and neutered.', '1', 'https://images.unsplash.com/photo-1518791841217-8f162f1e1131?auto=format&fit=crop&w=1200&q=85', 'Available', '1', '2026-09-25 20:50:47', '2026-09-26 01:34:55'),
  ('4', 'Bella', 'Dog', 'Beagle', '48', 'Female', 'Medium', 'Negombo', 'Bella is a cheerful, scent-driven Beagle who has already found a loving forever home. Her story is shared to celebrate a successful adoption.', 'Cheerful, sociable, curious and resilient.', 'Healthy and happy in her new home.', '1', 'https://images.unsplash.com/photo-1507146426996-ef05306b995a?auto=format&fit=crop&w=1200&q=85', 'Adopted', '0', '2026-09-25 20:50:47', '2026-09-25 20:50:47'),
  ('5', 'Coco', 'Cat', 'Persian', '24', 'Female', 'Medium', 'Colombo', 'Coco is a calm, elegant Persian who enjoys peaceful homes and gentle brushing. She is currently with a foster carer while her adoption plan is being reviewed.', 'Quiet, gentle, routine-oriented and affectionate.', 'Under veterinary review; grooming support required.', '0', 'https://images.unsplash.com/photo-1573865526739-10659fec78a5?auto=format&fit=crop&w=1200&q=85', 'Pending', '1', '2026-09-25 20:50:47', '2026-09-25 20:50:47'),
  ('6', 'Rocky', 'Dog', 'German Shepherd', '36', 'Male', 'Large', 'Kurunegala', 'Rocky is a thoughtful, loyal companion who would suit an active adopter experienced with large, intelligent breeds.', 'Loyal, intelligent, protective and trainable.', 'Healthy, vaccinated and microchipped.', '1', 'https://images.unsplash.com/photo-1589941013453-ec89f33b5e95?auto=format&fit=crop&w=1200&q=85', 'Available', '1', '2026-09-25 20:50:47', '2026-09-25 20:50:47'),
  ('7', 'Nala', 'Cat', 'Mixed Breed', '24', 'Female', 'Small', 'Kandy', 'Nala is a sweet, observant cat who enjoys a predictable routine and a sunny spot near her favorite person.', 'Sweet, observant, playful and moderately active.', 'Healthy with completed routine vaccinations.', '1', 'https://images.unsplash.com/photo-1519052537078-e6302a4968d4?auto=format&fit=crop&w=1200&q=85', 'Available', '1', '2026-09-25 20:50:47', '2026-09-25 20:50:47'),
  ('8', 'Oliver', 'Rabbit', 'Mini Lop', '12', 'Male', 'Small', 'Colombo', 'Oliver is a friendly Mini Lop who is learning litter habits and enjoys a calm home with space to explore.', 'Gentle, curious, food-motivated and friendly.', 'Healthy; spay/neuter and parasite care complete.', '1', 'https://images.unsplash.com/photo-1585110396000-c9ffd4e4b308?auto=format&fit=crop&w=1200&q=85', 'Reserved', '0', '2026-09-25 20:50:47', '2026-09-25 20:50:47');

-- adoption_applications (1 rows)
INSERT INTO `adoption_applications` (`id`, `user_id`, `pet_id`, `application_reference`, `full_name`, `email`, `phone`, `address`, `home_type`, `living_situation`, `previous_pet_experience`, `family_members`, `working_hours`, `experience_with_animals`, `reason`, `additional_information`, `status`, `created_at`, `updated_at`) VALUES
  ('5', '2', '1', 'PAW-2026-00124', 'Ashan Perera', 'ashan@example.com', '+94 77 123 4567', 'Colombo, Sri Lanka', 'Apartment', 'Living with family', 'Some experience caring for family pets', '3', 'Office hours, usually 9am to 5pm', 'Comfortable with dogs and calm handling', 'We want to build a calm, responsible home where Luna can feel safe and loved.', 'Happy to meet her for a home compatibility conversation.', 'SUBMITTED', '2026-09-26 01:02:12', '2026-09-27 06:04:56');

-- success_stories (5 rows)
INSERT INTO `success_stories` (`id`, `pet_name`, `image`, `story`, `adoption_date`, `created_at`) VALUES
  ('1', 'Bella', 'https://images.unsplash.com/photo-1507146426996-ef05306b995a?auto=format&fit=crop&w=1000&q=85', 'Bella found a family that celebrates her curiosity, daily walks and wonderfully noisy nose. Her story is a reminder that a patient match can change everything.', '2025-11-14', '2026-09-25 20:50:47'),
  ('2', 'Mochi', 'https://images.unsplash.com/photo-1574158622682-e40e69881006?auto=format&fit=crop&w=1000&q=85', 'Mochi was adopted by a first-time guardian who learned her favorite games and built a confident little routine around her.', '2025-08-22', '2026-09-25 20:50:47'),
  ('3', 'Shadow', 'https://images.unsplash.com/photo-1553884828-4f8827a57b7b?auto=format&fit=crop&w=1000&q=85', 'Shadow found a calm home with a patient guardian. He now enjoys quiet afternoons, soft toys and a sunny garden.', '2025-05-09', '2026-09-25 20:50:47'),
  ('4', 'Coco', 'https://images.unsplash.com/photo-1573865526739-10659fec78a5?auto=format&fit=crop&w=1000&q=85', 'Coco is currently building her next chapter with a foster family. Her story shows how care, patience and shared decisions create trust.', '2025-03-18', '2026-09-25 20:50:47'),
  ('5', 'Bruno', 'https://images.unsplash.com/photo-1558788353-f76d92427f16?auto=format&fit=crop&w=1000&q=85', 'Bruno was matched with an active family who gave him the time, guidance and structure he needed to thrive.', '2024-12-02', '2026-09-25 20:50:47');

