INSERT INTO `feedback` (`id`, `user_id`, `rating`, `comment`, `status`, `created_at`) VALUES
  ('1', '2', '5', 'The adoption process felt calm and transparent. We knew what to expect at every step.', 'APPROVED', '2026-09-25 20:50:47'),
  ('2', NULL, '5', 'A thoughtful platform that makes responsible adoption easier to begin.', 'APPROVED', '2026-09-25 20:50:47'),
  ('3', NULL, '4', 'We found a wonderful match and felt supported after bringing our pet home.', 'APPROVED', '2026-09-25 20:50:47');

